from datetime import datetime
import numpy as np

class MovieBookingSystem:
    TIME_FORMAT = '%H:%M'
    SEAT_AVAILABLE = 0
    SEAT_BOOKED = 1

    def __init__(self):
        self._movies = []

    @property
    def movies(self):
        return self._movies

    @movies.setter
    def movies(self, value):
        self._movies = value

    def add_movie(self, name, price, start_time, end_time, n):
        movie = {
            'name': name,
            'price': price,
            'start_time': self._parse_time(start_time),
            'end_time': self._parse_time(end_time),
            'seats': np.zeros((n, n))
        }
        self._movies.append(movie)

    def _parse_time(self, time_str):
        return datetime.strptime(time_str, self.TIME_FORMAT)

    def book_ticket(self, name, seats_to_book):
        movie = self._find_movie_by_name(name)
        if movie is None:
            return "Movie not found."

        if not self._can_book_seats(movie, seats_to_book):
            return "Booking failed."

        self._book_seats(movie, seats_to_book)
        return "Booking success."

    def _find_movie_by_name(self, name):
        for movie in self._movies:
            if movie['name'] == name:
                return movie
        return None

    def _can_book_seats(self, movie, seats_to_book):
        for seat in seats_to_book:
            if movie['seats'][seat[0]][seat[1]] != self.SEAT_AVAILABLE:
                return False
        return True

    def _book_seats(self, movie, seats_to_book):
        for seat in seats_to_book:
            movie['seats'][seat[0]][seat[1]] = self.SEAT_BOOKED

    def available_movies(self, start_time, end_time):
        parsed_start = self._parse_time(start_time)
        parsed_end = self._parse_time(end_time)

        result = []
        for movie in self._movies:
            if self._is_movie_in_range(movie, parsed_start, parsed_end):
                result.append(movie['name'])

        return result

    def _is_movie_in_range(self, movie, parsed_start, parsed_end):
        return parsed_start <= movie['start_time'] and movie['end_time'] <= parsed_end
